<?php

namespace App\Admin\Modules\ApiAccess;

use App\Service\Api\ApiSettings;
use App\Service\Api\EndpointCatalog;

if (!defined('ABSPATH')) exit;

/** Structured, escaped help content. Rendering never reads a credential or patient record. */
final class HelpContent
{
    public static function field(string $key): array
    {
        $fields = [
            'flow_slug' => ['This names one booking setup in the address your app calls.', 'Choose a different identifier for each setup you publish.', 'Enter 2–64 lowercase letters, numbers or hyphens. The first character must be a letter.', 'For initial-consultation, your app reads /booking-flows/initial-consultation.', 'Treat this address as an app contract. Removing its publication stops new calls; changing the linked setup makes apps reload its structure.', 'booking'],
            'api-booking-identifier' => ['This is the short name in the booking address your app calls.', 'Choose a different identifier for each booking flow.', 'Use 2–64 lowercase letters, numbers or hyphens, beginning with a letter.', 'initial-consultation gives your app /booking-flows/initial-consultation.', 'The identifier is fixed once created. Removing it stops new bookings at that address. Your app must reload when booking rules change.', 'booking'],
            'api-booking-appointment_type_id' => ['Choose what the patient will book through this app flow.', 'Every flow needs one appointment type.', 'Select the service from the list loaded from Cliniko.', 'Choose Initial consultation for your new-patient appointment flow.', 'Selecting here does not publish it automatically. Approve it in Publish API too. Price and duration always come from Cliniko.', 'booking'],
            'api-booking-patient_form_template_id' => ['Choose the questionnaire your app will receive when someone books.', 'Every flow needs a blank Cliniko form template.', 'Select the form, save a draft, then open the flow to review its questions and answer checks.', 'Choose your Intake form to ask the patient those questions in the app.', 'Changing the template resets the old question checks. Required answers and choice lists come from Cliniko. This never loads completed patient forms.', 'booking'],
            'api-booking-scheduling' => ['Choose who selects the appointment time: the patient or the website.', 'Every flow has one scheduling policy.', 'Choose Patient chooses for an app calendar, or Automatically choose for the earliest available appointment.', 'A follow-up app can ask for a preferred doctor and time. An urgent queue can use the next available slot.', 'Automatic selection happens when the booking is submitted, not when the app reads the form. Reading the structure never reserves a slot.', 'booking'],
            'api-booking-payment' => ['Choose how this booking is paid for.', 'Choose a payment service unless the Cliniko appointment is free.', 'Select Stripe, Tyro Health or No payment. Your developer follows the corresponding payment endpoints.', 'Use Stripe for a paid consultation or No payment for a genuinely zero-priced service.', 'No payment does not make a paid appointment free. The website checks the Cliniko price and rejects that combination.', 'booking'],
            'api-booking-enable' => ['Turn this on when the booking flow is ready for the app to use.', 'Leave it off while preparing and reviewing questions.', 'Publish its service and form, enable the patient booking/payment groups, configure patient login and approve app permissions, then enable this flow.', 'Start with a draft for your first test, then enable it after your developer has an approved patient app.', 'Enabling never permits guest bookings. Disable API flow remains available during a Cliniko outage. Existing attempts retain their original protected routes.', 'booking'],
            'api-booking-rules' => ['Add checks on answers without choosing how the app should display the questions.', 'Optional. Keep defaults to use the Cliniko form without extra checks.', 'Open a question to set a character limit, accept only numbers, require a date or allow only listed answers.', 'A short reference can allow 20 characters. A category can accept only the approved answers entered one per line.', 'The website checks these rules again on submission. Dates use YYYY-MM-DD. A new form template resets old question checks; save and review it.', 'booking'],
            'slug' => ['This is the short name used in the web address your app connects to.', 'You need a name for the API. If you are unsure, keep cliniko-api.', 'Enter a short name such as cliniko-api or api. You do not need to enter your whole website address.', 'Choosing api makes the address end in /wp-json/api/v1.', 'Changing this after an app is launched can stop that app working. Arrange the change with your developer first.', 'migration'],
            'appointment_types' => ['Choose which clinic services an app may show and book, such as an initial consultation or a follow-up.', 'Select services if the app will show services, available times or make bookings. Leaving every service unticked makes none available.', 'Tick the services you want to offer in the list loaded from Cliniko, then save. Use Find a service to search by name. You do not need to look up or type service numbers.', 'Tick Initial consultation and Follow-up if you want apps to offer those two services. Leave staff-only services unticked.', 'Loading or searching the list does not publish anything. Previously selected services missing from Cliniko stay checked until you remove them. Review these before saving. A newly added service is not automatically selected.', 'booking'],
            'form_templates' => ['Choose which blank patient questionnaires an app may use when making a booking.', 'Bookings need at least one approved questionnaire. Allowing an app to display its questions is a separate choice under Route groups.', 'Tick the questionnaires you want to offer in the list loaded from Cliniko, then save. Use Find a form template to search by name. No form numbers need to be entered.', 'Tick your Intake questionnaire if patients should complete it when booking. Leave staff-only forms unticked.', 'This approves blank questions, not completed patient answers. Previously selected forms missing from Cliniko stay checked for review; loading the list does not publish new forms automatically.', 'booking'],
            'read_limit' => ['This limits how often an app can ask for information, such as services or available times. It helps prevent excessive traffic.', 'Keep the starting value of 180 unless your developer recommends a change.', 'Enter the maximum number of information requests allowed in ten minutes. Raising it allows more traffic; lowering it may make users wait.', 'One app screen might ask for the service list and then available times. Those are two requests, not two patients.', 'People on a shared internet connection may share a limit. Ask your developer to investigate waiting errors before increasing it.', 'server'],
            'write_limit' => ['This limits actions that change something, such as starting a booking, taking payment or confirming an appointment.', 'Keep the starting value of 20 unless your developer recommends a change.', 'Enter the maximum number of these actions allowed in ten minutes. Choose enough for a complete booking, not just the first step.', 'Starting a booking, processing its payment and confirming it are three separate actions.', 'Too low can interrupt genuine bookings. Too high allows more automated activity. Review changes with your developer.', 'booking'],
            'audit_days' => ['Choose how long to keep the activity history shown in Audit events. This history helps staff investigate problems.', 'Keep the starting value of 14 days unless your clinic needs a different support or privacy period.', 'Enter a number of days from 1 to 90.', '14 keeps about two weeks of history. Older entries are removed by the scheduled cleanup.', 'This setting is not a backup and does not delete Cliniko patient records. Other plugin logs have separate settings.', 'troubleshooting'],
            'issuer' => ['This tells your website which sign-in service it should trust when patients log in through an app.', 'Only needed for patient sign-in. You can leave it empty while OAuth is disabled.', 'Ask the person setting up app sign-in for the exact issuer address. Copy it without changing it, including a slash at the end if supplied.', 'Ask: "What exact issuer address should I paste into the API Access settings?"', 'Do not use your clinic website address just because it is familiar. The correct address comes from the sign-in service setup.', 'oauth'],
            'audience' => ['This is the name the sign-in service uses for this API. It helps your website reject login passes meant for a different service.', 'Only needed for patient sign-in. Leave it empty while OAuth is disabled.', 'Ask your sign-in developer for the API audience value and copy it exactly. This value is assigned during setup; you should not invent it here.', 'Your developer might give you cliniko-patient-api. Enter that only if it is the value they actually configured.', 'This is not automatically the app name, website address or API base slug.', 'oauth'],
            'introspection_url' => ['This is the address your website uses to ask the sign-in service: "Is this patient\'s login pass still valid?"', 'Only needed for patient sign-in. Leave it empty while OAuth is disabled.', 'Ask your sign-in developer for the token-checking address, also called the introspection endpoint. Paste the full secure address they supply.', 'Ask: "Which introspection endpoint should WordPress use to check app logins?"', 'The address of the login page is not the same thing. Your developer must also confirm that the sign-in service supports this plugin.', 'oauth'],
            'introspection_client' => ['This identifies your WordPress website to the sign-in service when it checks a patient\'s login pass.', 'Only needed for patient sign-in. It works together with Introspection client secret.', 'Ask your sign-in developer for the client ID assigned to WordPress for checking logins. Copy it exactly.', 'Ask: "What client ID should the WordPress website use for introspection?"', 'The mobile app has a different ID. Do not copy the app\'s ID into this field unless your developer explicitly confirms it.', 'oauth'],
            'introspection_secret' => ['This is the private password your website uses when asking the sign-in service to check patient logins.', 'Enter it when first setting up patient sign-in, or when your developer replaces that password.', 'Get the introspection secret from your sign-in developer through a secure channel. Paste it into Website connection password and save. On later visits, leave it blank to keep the saved password.', 'An empty field after saving is normal: the plugin does not show the saved password again. Show entered password only reveals what you have just typed.', 'Never put this password in the mobile app or send it in ordinary support messages. It is not your WordPress account password.', 'oauth'],
            'name' => ['Give this application a name your team will recognise in the dashboard.', 'Every application approval needs a name. You choose it yourself.', 'Enter a clear name that describes the app or partner using it.', 'Patient Android App or Partner Booking System.', 'The name is just a label. It does not give the application permission or act as its password.', 'server'],
            'external_id' => ['This links the app you approve here to the same app registered with the patient sign-in service.', 'Required for OAuth mobile/browser applications. Leave it empty for Trusted server integrations.', 'Ask the app\'s sign-in developer for its registered client ID. Copy that ID exactly.', 'The developer might supply patient-mobile-app. Use their actual value, not this example.', 'This is the app\'s ID, not the WordPress login-checking ID entered in Website connection ID.', 'oauth'],
            'expires_at' => ['Choose when this application\'s permission to use your API ends.', 'Every application needs a future expiry date. Set a reminder to review it before then.', 'Select a date that matches how long you intend to allow this application access. You can edit it later.', 'For a short partner trial, choose the agreed trial end date rather than giving long-term access.', 'After expiry, the app stops being accepted even if the patient can still sign in. Expiry uses the end of the selected day in UTC, not your clinic\'s local time.', 'server'],
            'subject' => ['This identifies one patient in the sign-in service, so you can link their app login to the correct clinic account.', 'Needed for each patient who will view their own records through an app.', 'Ask your sign-in developer for that patient\'s exact subject ID. Pair it with the correct WordPress patient account below.', 'Ask: "What is this test patient\'s subject ID in our sign-in service?"', 'Do not guess using an email address. Linking the wrong person could give them access to someone else\'s records.', 'oauth'],
            'user_id' => ['This selects the existing WordPress patient account that belongs to the app user you are linking.', 'Needed when linking a patient\'s app login to their clinic account.', 'Ask your site administrator for the number of the correct WordPress user account. Check the person\'s identity before saving.', 'If the WordPress account number is 7, enter 7. Their Cliniko patient number may be different.', 'Use the WordPress number, not the Cliniko number. The account must already be active and its link to Cliniko verified; saving here does not do that verification.', 'oauth'],
            'api-master-switch' => ['Turn this on to let other apps connect to the API managed by this dashboard.', 'Leave it off until you are ready to test or launch an app. Your existing website features have separate controls.', 'Tick Enable API Access and save. Then select only the features your app needs.', 'A first test can simply check whether the API is available, without reading patient records or making a booking.', 'Turning this off stops apps using this API. It does not turn off every older website route in the plugin.', 'server'],
            'route-groups' => ['Choose what other apps may do through your website. Each group switches a related set of features on or off.', 'Select only the features your app needs. You do not have to enable everything.', 'Booking discovery lets apps show services and times. Authenticated patient booking lets signed-in, verified patients make their own bookings. Patient profile and appointments lets signed-in patients view their own information.', 'For an app that only shows services, start with Booking discovery and tick the services you want to publish. Patient login is not needed for that.', 'Patient features need sign-in setup. Bookings need selected services and questionnaires. Authenticated patient booking also needs Booking payment and progress for payment and confirmation. Guest bookings are not exposed by this API.', 'booking'],
            'allowed-browser-origins' => ['List the other websites that may connect to this API from a visitor\'s browser.', 'Usually needed for a patient portal hosted on another website. A native mobile app generally does not need this setting.', 'Enter each approved website\'s secure address on its own line, without a page name or path. Ask your developer for the exact address if unsure.', 'Use https://portal.example.com, not https://portal.example.com/login. On a local or development website, http://localhost:3000 is also allowed. Staging and live websites require HTTPS.', 'Adding a website does not give its users access to patient records. Patient sign-in and app permissions are still required.', 'browser'],
            'application-type' => ['Choose how the app will sign in, or whether it is a trusted partner server.', 'Choose Patient app for website-account, Google or Apple login. Choose OAuth mobile/browser application for a separate sign-in service. Choose Trusted server integration for a partner backend.', 'Ask your developer which login method they will implement. Both patient app types have public identifiers, not permanent shared passwords.', 'Website-account login screen: Patient app. Keycloak sign-in service: OAuth app. Partner service-list backend: Trusted server. Patient bookings require Patient app or OAuth app.', 'A trusted server key cannot access patient-account information, create bookings or process payments. A public App ID alone never proves who the patient is.', 'wordpress'],
            'google_client_id' => ['The public Google application ID this website expects in a Google login token.', 'Needed only when this Patient app offers a Google sign-in button.', 'Ask your developer for the exact Google token audience used by the SDK; paste that ID, not a password.', 'It looks like 123456-your-app.apps.googleusercontent.com.', 'Platform registrations may use different IDs. Never paste a Google client secret here or embed it in the app.', 'social'],
            'google_presenter_id' => ['An optional second Google app ID for certain native mobile sign-in setups.', 'Only if the mobile app has a different Google ID from the website connection above. Otherwise leave it empty.', 'Ask the developer whether Google returns a separate native application ID as the authorized presenter, and copy it exactly.', 'An Android registration can identify the mobile app while a web registration identifies the website receiving its login proof.', 'Do not guess this value or paste a secret. When supplied, the website requires the Google token to identify this exact presenter.', 'social'],
            'apple_client_id' => ['The public Apple application ID this website expects in an Apple login token.', 'Needed only for an Apple sign-in button in this Patient app.', 'Your developer supplies the bundle ID or Services ID used as the identity-token audience.', 'A native app might use com.example.patient; a web flow uses its registered Services ID.', 'Do not enter an Apple private key or patient email. Configure required domains and return URLs at Apple.', 'social'],
            'access_minutes' => ['How long a patient access pass works before the app renews it.', 'Applies to WordPress-issued JWT sessions, including direct Google/Apple exchanges. External OAuth uses provider settings.', 'Choose 5–30 minutes; default 15. Your developer implements renewal so patients are not repeatedly asked for a password.', 'With 15 minutes, the app renews the access pass after about a quarter of an hour.', 'Logout and dashboard revocation invalidate the pass immediately, without waiting for expiry.', 'wordpress'],
            'refresh_days' => ['The longest a WordPress-issued app session lasts without another sign-in.', 'Applies to WordPress, Google and Apple JWT sessions issued here.', 'Choose 1–30 days; default seven. Counted from the original login.', 'Renewing a seven-day session on day six does not extend it beyond day seven.', 'The private renewal pass rotates after every use. Replace both tokens together and avoid parallel renewals.', 'wordpress'],
            'registration_role' => ['The patient account type assigned when someone signs up through an approved app.', 'Needed only when you enable new-patient registration.', 'Choose one of the patient roles already configured for clinic sync. The app cannot choose it.', 'New mobile-app patients might receive your normal patient or client role, with no administration rights.', 'Administrator, editor and other elevated roles are excluded. Signup stays pending until the existing verification and approval flow completes.', 'registration'],
            'approved-scopes' => ['These checkboxes are the application\'s permissions. Choose which tasks it may carry out.', 'Choose only the tasks this particular application needs.', 'Use patient:read to view the signed-in patient\'s profile; patient:write to update fields allowed by the active onboarding scheme; patient:onboarding to read and complete missing profile fields; appointments:read for appointments and appointment totals; communications:read for messages and unread totals; communications:write to send messages or mark them read; attachments:read to view documents; attachments:write to upload, describe or archive documents; booking:create to start, pay for and confirm bookings; booking:read to check booking progress. catalog:read allows service and questionnaire lists; availability:read allows clinicians and times.', 'An app that only shows a patient their appointments needs appointments:read. Add communications or attachments permissions only when the app needs those features. Add patient:read if it shows the profile and patient:write for profile edits. Add patient:onboarding only when the app must complete missing profile data.', 'Your sign-in developer must allow the same permissions at the sign-in service. These permissions never give a patient access to another patient\'s account.', 'oauth'],
            'bearer-authentication' => ['This lets a patient sign in through your app and safely view their own clinic information.', 'You need this for personal profiles and appointment history. You do not need it just to show public services and available times.', 'Arrange a compatible sign-in service with your developer first. Then enter the connection details they supply, approve the app and link a test patient account.', 'Think of a token as a temporary login pass: the patient signs in, the app receives a pass, and your website checks it before showing their records.', 'Switching this on does not create a login screen. If no sign-in service has been set up yet, leave it off and start with the patient-login tutorial.', 'oauth'],
        ];
        if (!isset($fields[$key])) return ['intro' => '', 'sections' => [], 'tutorial' => 'troubleshooting'];
        [$meaning, $needed, $entry, $example, $warning, $tutorial] = $fields[$key];
        return ['intro' => $meaning, 'sections' => [
            ['title' => 'Do I need this?', 'text' => $needed],
            ['title' => 'What should I enter or choose?', 'text' => $entry],
            ['title' => 'A practical example', 'text' => $example],
            ['title' => 'Be careful about', 'text' => $warning],
        ], 'tutorial' => $tutorial];
    }

    public static function tutorials(): array
    {
        return [
            'wordpress' => ['title' => 'Build a WordPress-account login screen', 'subtitle' => 'Use existing website accounts with revocable patient JWT sessions.', 'category' => 'Patient apps', 'steps' => 5],
            'registration' => ['title' => 'Register new patients from an app', 'subtitle' => 'Reuse the WordPress verification email and Cliniko binding flow for new accounts.', 'category' => 'Patient onboarding', 'steps' => 5],
            'social' => ['title' => 'Add Google and Apple sign-in buttons', 'subtitle' => 'Connect a verified social identity to the right existing patient.', 'category' => 'Patient apps', 'steps' => 5],
            'oauth' => ['title' => 'Patient mobile login with OAuth', 'subtitle' => 'Let a patient sign in to an app and see only their own clinic information.', 'category' => 'Patient apps', 'steps' => 7],
            'server' => ['title' => 'Connect a trusted backend', 'subtitle' => 'Give a partner system permission to show published services and available times.', 'category' => 'Server integrations', 'steps' => 5],
            'booking' => ['title' => 'Build a booking and payment flow', 'subtitle' => 'Understand what happens from choosing a service to confirming the appointment.', 'category' => 'Bookings', 'steps' => 6],
            'browser' => ['title' => 'Allow a browser application', 'subtitle' => 'Allow a patient portal on another website to connect to your clinic.', 'category' => 'Browser apps', 'steps' => 4],
            'migration' => ['title' => 'Change the API address safely', 'subtitle' => 'Change the connection address without leaving existing apps behind.', 'category' => 'Maintenance', 'steps' => 4],
            'troubleshooting' => ['title' => 'Diagnose a failed API request', 'subtitle' => 'Know what to check and what to send your developer when something fails.', 'category' => 'Troubleshooting', 'steps' => 4],
        ];
    }

    public static function dashboardGuide(): array
    {
        return [
            'Getting started' => 'An API is a connection that lets another app use selected features of your clinic website. Start here to check what is ready. You can offer services and available times without setting up patient sign-in. Add personal records and bookings only when you need them.',
            'Field help and tutorials' => 'Use a question-mark button to find out what a setting does, whether you need it and what to enter. If a value comes from a sign-in service, the help tells you what to ask your developer for. Tutorials walk through complete examples. The developer reference is optional; you can leave it closed.',
            'Publish API' => 'The master switch turns this managed API on or off. Route groups choose which features apps may use. Start with Booking discovery for services and times. Patient profile and appointments needs patient sign-in. Bookings need selected services and questionnaires. Authenticated patient booking also needs Booking payment and progress for payment and confirmation. Guest bookings are not exposed by this API.',
            'Booking flows' => 'Create an API-only booking setup here: choose the appointment type, form, scheduling, payment and optional answer checks. No shortcode or website form is required. Existing website-linked publications are labelled Legacy and can be made API-only without changing the web form. The response is structure-only JSON; apps handle presentation, success and errors. Read the endpoint contract for answer formats, revision checks and patient-token permissions.',
            'API address and changing its name' => 'Apps connect to the Base URL shown in Settings. Keep the starting name unless there is a reason to change it. If an app is already using it, plan a change with your developer first. The old address works for only 30 days after a rename.',
            'Published Cliniko IDs' => 'Choose services and questionnaires by ticking their names under Published appointment types and Published form templates. Their Cliniko numbers are handled automatically. Lists are cached for up to five minutes; previously selected items missing from Cliniko stay checked for review. Empty selections make nothing available. You are approving services and blank forms, not publishing completed patient records.',
            'Read/write limits' => 'These control how much traffic is allowed in ten minutes. Read means asking for information. Write means actions such as bookings or payments. Keep the starting values unless your developer recommends a change. Limits that are too low may make genuine users wait.',
            'Allowed browser origins' => 'Use this if a portal on another website connects through a browser. Add the exact website address, without a page path, one per line. HTTPS is required except when WordPress is in local or development mode, where HTTP is also accepted. Native phone apps generally do not need it. An allowed website still needs the right login and permissions to view patient information.',
            'Patient login methods' => 'Patient login has four sections. WordPress login issues patient JWT sessions for a custom app login screen using existing website accounts. External OAuth 2.0 contains the guided service setup. Social sign-in verifies Google/Apple identity tokens and issues patient JWTs. Sessions & expiry manages WordPress-issued session lifetimes and revocation. All methods are explicit choices; saving one section preserves the others and API publishing.',
            'Requests & responses' => 'Choose a walkthrough to see what leaves the app, what this website checks and what comes back. Data-journey tables explain each field. Examples are synthetic and copyable; the page does not send requests or retrieve real patient records.',
            'Registration and pending accounts' => 'Patient login → Registration controls website-account, Google/Apple and external OAuth signup independently. Choose a safe configured patient role and approve registration permission for each app. All methods reuse the existing WordPress verification email and clinic-linking rules. Signup returns a limited private receipt for progress/resend, never a patient access pass. Existing emails do not merge accounts, and service email verification does not replace the clinic email verification.',
            'Check saved connection' => 'This button checks whether your website can contact the sign-in service using the saved details. Editing those details disables the button until you save. A previous check is out of date when saved connection details or the password change. A successful check is not a complete patient-login test. Ask your developer to sign in through the app with a test patient and check what information appears.',
            'Applications' => 'Register approved apps and their permissions here. Patient apps use WordPress, Google or Apple JWT sessions. OAuth apps use an external service. Trusted server integrations receive a private key once, never for phones/public web pages or patient-account access. App IDs are public identifiers, not proof of patient identity.',
            'Scopes and application expiry' => 'Scopes are permissions: they choose the tasks an app may carry out. Select only what it needs. Set a future expiry date and review the approval before then. Revoke stops an app being accepted. Rotate key replaces a server password immediately, so arrange the change with its developer.',
            'Patient links' => 'This connects a person in the sign-in service to their existing WordPress patient account. Ask your developer for the exact sign-in identifier and your site administrator for the WordPress user number. Check that both belong to the same person. The account must already have a verified Cliniko link. Removing a mapping blocks personal API access for that login but does not delete the patient.',
            'Endpoint documentation and download' => 'This is the developer-facing list of available connections: what each does, what the app must send and what it receives back. The page shows which are active. Download active OpenAPI JSON gives your developer a current copy they can use with development tools. Download it again when settings change.',
            'Audit events and retention' => 'Audit events is the activity history used to trace errors and setting changes. Your developer can supply a request ID, a tracking number for an individual app action, to help find it. Audit retention chooses how many days of this history to keep; it does not delete clinic patient records.',
            'Booking retry and idempotency rules' => 'If an app loses its connection during payment or confirmation, do not immediately start another booking. The developer should check the existing booking first. The app must recognise repeated confirmation attempts so they do not create duplicate appointments. Some interrupted bookings need clinic review.',
            'Legacy website compatibility' => 'These controls manage the new app-facing API, not every older website connection. Some unsafe older connections have been retired. If an existing website form or payment screen relies on them, ask its developer to update that flow. Turning this API off does not restore those old connections.',
        ];
    }

    /** Content blocks keep every code example and dynamic URL escaped at rendering. */
    public static function tutorial(string $key): array
    {
        $guides = [
            'registration' => [
                ['title' => '1. Check the existing website flow first', 'text' => 'Patient sync, a low-privilege patient role, the verification email template and email delivery must already work. Ask your developer to review your privacy-consent, anti-spam and approval requirements.'],
                ['title' => '2. Approve each signup method', 'text' => 'Open Patient login → Registration. Choose website-account, Google/Apple and/or external OAuth registration. Select the patient role and confirm the review before saving. Other login and publishing settings remain unchanged.'],
                ['title' => '3. Approve the app’s signup permission', 'text' => 'Under Applications, give the patient or OAuth app Register new patient accounts permission. A trusted server key cannot register patient accounts. External OAuth also needs this permission and a verified email at the provider.'],
                ['title' => '4. Build the waiting-for-verification screen', 'text' => 'The app submits names, explicit privacy consent and the chosen registration proof. It receives a private onboarding receipt, not a login pass. WordPress sends the existing clinic verification email. The app can check progress and request another email, subject to cooldown and limits.'],
                ['title' => '5. Verify, approve, then sign in', 'text' => 'The patient opens the email link. The existing website verifier completes the Cliniko binding or creates a patient according to the existing rules. The app signs in only after verification and approval. Social registration uses the provider’s verified email; Apple relay email may not match an existing clinic record. Existing users should sign in or ask the clinic to link identities rather than registering again.'],
            ],
            'wordpress' => [
                ['title' => '1. Reuse existing patient accounts', 'text' => 'Patients use their website username/email and password in the app. The account must already be active, verified and linked to Cliniko. This is not patient registration or account approval.'],
                ['title' => '2. Review login requirements', 'text' => 'Ask the developer to check your two-factor, CAPTCHA and membership-login requirements first. Known interactive MFA integrations are blocked. Do not enable an API password shortcut that bypasses required checks.'],
                ['title' => '3. Register a Patient app', 'text' => 'Under Applications, choose Patient app · WordPress / social JWT. Select only the required permissions and an approval expiry. Copy its public App ID to the developer.'],
                ['title' => '4. Enable and publish deliberately', 'text' => 'Under Patient login → WordPress login, enable the method after the review. Separately enable API Access and the required patient-data groups in Publish API. Saving either page preserves the other settings.'],
                ['title' => '5. Test login, renewal and withdrawal', 'text' => 'The developer builds the app screens, secure token storage, serialized renewal and logout. Test a valid patient, a wrong password, an inactive account and a revoked app session before rollout. See Requests & responses for the exact data journey.'],
            ],
            'social' => [
                ['title' => '1. Register the social application', 'text' => 'Your developer registers the real app at Google or Apple and configures the required platform, consent, domains and return addresses. This dashboard does not create those external registrations.'],
                ['title' => '2. Configure its public ID here', 'text' => 'Register a Patient app under Applications. Enter the Google client ID or Apple bundle/Services ID used in its identity tokens. These values are public IDs—not passwords or private keys.'],
                ['title' => '3. Enable a social method', 'text' => 'Under Patient login → Social sign-in, explicitly enable Google and/or Apple. Separately publish the patient API routes and approve the app’s required permissions.'],
                ['title' => '4. Link one verified test identity', 'text' => 'Confirm the social identity belongs to the existing patient. Under Patient links, choose the service and enter its verified subject ID and the patient’s WordPress account. Never match accounts by email alone.'],
                ['title' => '5. Have the developer complete the login flow', 'text' => 'The app first requests a single-use challenge, includes its nonce in the social sign-in, then sends the returned signed ID token to this website. The website verifies it and returns a patient JWT only for a linked, approved patient. Test replay, wrong app registration, unlinked users and revoked sessions.'],
            ],
            'oauth' => [
                ['title' => 'What is this for?', 'text' => 'Imagine a patient opens your clinic app to see their next appointment. The app must prove who they are before showing private information. OAuth is a way to do that using a separate sign-in service. After login, the app gets a temporary login pass, called a token. Your website checks that pass and finds the matching patient account.'],
                ['title' => 'Do you need to set this up?', 'text' => 'Yes if patients will see their personal details or appointment history. No if the app only displays public services and available times. This plugin checks app logins; it does not supply the separate sign-in service or build the login screen for you.'],
                ['title' => 'Who does what?', 'items' => ['Clinic staff choose which features the app may use and confirm which patient accounts should be linked.', 'Your developer sets up a compatible sign-in service, builds the app login, supplies the connection values and checks that the whole flow works.', 'You do not need to invent the values in the OAuth fields. If you do not have them, ask the developer before enabling patient access.']],
                ['title' => '1. Tell your developer what patients should be able to do', 'text' => 'For example: "Patients should sign in, see their next appointment and view their profile. They must never see another patient\'s records." Start with a test account, not a live patient rollout.'],
                ['title' => '2. Ask for the sign-in setup details', 'text' => 'In the guided setup, choose your service to see its specific instructions and value locations. Use Copy developer checklist to send the tailored request. Not every service works directly with this plugin; read its compatibility note before proceeding. The technical requirements are in the separate developer reference at the end of this guide.', 'items' => ['Exact token issuer: which sign-in service the website should trust.', 'Expected API audience: the name given to this API in the sign-in service.', 'Introspection endpoint: the address used to check whether a login pass is valid.', 'Introspection client ID and secret: the website\'s ID and private password for making that check.', 'Provider client ID: the separate ID assigned to the patient app.', 'A test patient\'s subject ID: that person\'s identifier in the sign-in service.']],
                ['title' => '3. Fill in the website connection settings', 'text' => 'Open the Patient login tab and use the guided setup. Copy supplied values into Your sign-in service and Website connection. Review highlights anything missing. Keep sign-in off while saving an unfinished setup. When ready, enable it and Save patient-login settings. Separately enable API Access and choose Patient profile and appointments under Publish API for personal records. Saving either tab preserves the other tab\'s settings.'],
                ['title' => '4. Approve the patient app', 'text' => 'Open Applications and add an OAuth mobile/browser application. Give it a recognisable name, paste the app\'s Provider client ID and choose a future expiry. Select patient:read if it should show a profile and appointments:read if it should show appointments. These are permissions, not passwords.'],
                ['title' => '5. Link one test patient', 'text' => 'In Patient links, enter the supplied issuer, that test patient\'s subject ID and the number of their existing WordPress patient account. Double-check that both accounts belong to the same person. The WordPress account must already be active and have a verified link to Cliniko. Do not guess the link from an email address.'],
                ['title' => '6. Check the connection, then try a real app login', 'text' => 'In Check & finish, click Check saved connection after saving. Passing means the website can contact the sign-in service and use its saved password; it does not prove patient login works. Ask your developer to sign in through the app with the test patient and confirm the app shows only that person\'s information. Also test an unlinked account and make sure it cannot see patient records.'],
                ['title' => '7. Agree how to remove access', 'text' => 'Before launch, decide who will manage app approvals and account links. Revoke an application to stop that app using the API. Remove a patient mapping to stop that app-login account accessing patient records. Neither action deletes the patient\'s WordPress or Cliniko account.'],
                ['title' => 'What success looks like', 'text' => 'The test patient can sign in and see their own profile or appointments. An unlinked account cannot view patient data. The developer has tested expired logins and your team knows how to withdraw access.'],
            ],
            'server' => [
                ['title' => 'What is a trusted backend?', 'text' => 'It is a separate computer system run by your organisation or a trusted partner, rather than an app installed on a patient\'s phone. It can keep a private access password. Use this connection for service lists and bookings, not for reading patient-account information.'],
                ['title' => '1. Decide what the partner needs', 'text' => 'Agree whether they only need to show clinic services or also book appointments. Enable API Access and the relevant Route groups. Tick the services you want to offer under Published appointment types and save.'],
                ['title' => '2. Add an application approval', 'text' => 'In Applications, select Trusted server integration. Use a clear name, leave Provider client ID empty and choose an expiry. Select catalog:read for services and questionnaires, and availability:read if they need clinicians and available times.'],
                ['title' => '3. Save the private access key', 'text' => 'Registering the application displays a key once. Treat it like a password. Give it to the partner developer through a secure channel so they can store it on their server. Do not put it in a phone app, web page or ordinary email.'],
                ['title' => '4. Ask the developer to test the connection', 'text' => 'Give the developer the Base URL shown in Settings and your chosen permissions. Ask them to confirm their system can retrieve only the services you approved. The exact request format is in the developer reference below.'],
                ['title' => '5. Review or withdraw permission', 'text' => 'Use Edit scopes / expiry to change the allowed tasks or expiry date. Revoke stops the application being accepted. Rotate key replaces its password immediately, so coordinate with the developer before doing that.'],
            ],
            'booking' => [
                ['title' => 'How an app booking works', 'flow' => ['Patient chooses a clinic service and available time.', 'App collects the required booking details and answers.', 'Website checks the signed-in patient and creates their booking draft.', 'Payment is checked if the service requires it.', 'Website confirms the appointment and the app shows the result.']],
                ['title' => '1. Choose which services can be booked', 'text' => 'Enable Booking discovery, Authenticated patient booking and Booking payment and progress. Tick the offered services under Published appointment types and the required questionnaires under Published form templates. If the app displays their questions, enable the Published form templates route group too.'],
                ['title' => '2. Require a verified patient account', 'text' => 'Complete the patient-login tutorial. Every API booking requires an active verified patient account; guests and trusted server keys cannot make bookings. Keep Booking payment and progress enabled for payment and confirmation. Your developer must approve the app\'s required booking permissions.'],
                ['title' => '3. Agree what the booking screens collect', 'text' => 'Use a test service and questionnaire with your developer. Confirm that available times come from the clinic, the form asks the right questions and the app does not invent its own price.'],
                ['title' => '4. Understand the draft stage', 'text' => 'Starting a booking creates a draft, not a confirmed appointment. The app receives private details used to continue that booking. A draft does not reserve the chosen time, and unfinished drafts may be cleaned up after about 30 minutes.'],
                ['title' => '5. Test payment and confirmation', 'text' => 'Use payment test accounts and staging clinic data. Check both a successful payment and a declined one. Your website must verify payment before confirming a paid appointment. Test a free service too if you offer one.'],
                ['title' => '6. Test what happens if the connection drops', 'text' => 'Ask the developer to test a lost connection after payment or confirmation. The app should check the booking\'s progress and avoid creating duplicates. If the outcome needs clinic review, investigate it before trying another booking or payment.'],
            ],
            'browser' => [
                ['title' => 'When do I need this?', 'text' => 'Use this when a patient portal runs on another website and connects to your clinic through the browser. A native phone app generally does not need this setting. It allows a website connection; it does not give someone permission to read patient records.'],
                ['title' => '1. Get the portal website address', 'text' => 'Ask your developer for the exact secure website address hosting the portal, such as https://portal.example.com. Use the website address without a page name like /login.'],
                ['title' => '2. Add it to the allowed list', 'text' => 'In Settings, put that address into Allowed browser origins and save. If there are several approved websites, enter one per line. Do not allow unknown websites.'],
                ['title' => '3. Set up patient login separately', 'text' => 'If the portal shows personal information, follow the patient-login tutorial too. Adding its website to this list does not replace login, app approval or matching each person to their patient account.'],
                ['title' => '4. Test from the actual portal', 'text' => 'Ask the developer to open the portal and try a permitted action. If it fails, they should check whether the website address is allowed or whether login permissions are wrong. Those are different problems.'],
            ],
            'migration' => [
                ['title' => 'Why should I plan this?', 'text' => 'Apps save the address they use to reach your website. Changing API base slug changes that address. The old address keeps working for 30 days to give you time to move existing apps; it is not a permanent backup address.'],
                ['title' => '1. Agree the change with your developer', 'text' => 'List the phone apps, portals and partner systems using the API. Agree how they will update within 30 days. If you are unsure who is using it, do not rename it yet.'],
                ['title' => '2. Save the new name', 'text' => 'Change API base slug in Settings, tick Confirm changing an active base URL and save. Ask your developer to check both the new and previous addresses work during the transition.'],
                ['title' => '3. Give each developer the new address', 'text' => 'Share the new Base URL shown in Settings and download a fresh endpoint document for developers. Existing phone apps may need an app update.'],
                ['title' => '4. Finish before the old address expires', 'text' => 'Check the expiry date shown in Settings. Get confirmation that every supported app has moved to the new address. After that date, the old address stops working.'],
            ],
            'troubleshooting' => [
                ['title' => '1. Record what happened', 'text' => 'Write down the time, which app was used and what the person was trying to do. Ask the developer for the error message and request ID, the tracking number for that one attempt. Do not send passwords, login passes or patient answers in a support message.'],
                ['title' => '2. Check the basic settings', 'text' => 'Is API Access enabled? Is the required Route group selected? Has the application approval expired? Are services and questionnaires ticked and saved? Ask the developer to confirm the app uses the Base URL currently shown in Settings.'],
                ['title' => '3. Check the part that failed', 'text' => 'If login works but personal records do not appear, check that the right patient account is linked and verified. If no services appear, check the services are ticked under Published appointment types and saved. If users are asked to wait, ask the developer to check request limits before raising them.'],
                ['title' => '4. Investigate bookings before repeating them', 'text' => 'If payment or confirmation failed, have the developer check the booking\'s progress and the clinic check its records first. The patient should not have to pay again because the app lost a connection. Use Audit events and the request ID to help trace the failure.'],
            ],
        ];
        $blocks = $guides[$key] ?? $guides['troubleshooting'];
        $blocks[] = ['title' => 'For your developer: technical reference', 'developer' => self::developerTutorial($key)];
        return $blocks;
    }

    private static function developerTutorial(string $key): array
    {
        $base = rest_url(ApiSettings::namespace());
        if ($key === 'registration') return [
            ['title' => 'WordPress registration', 'code' => 'POST ' . $base . '/auth/register' . "\nContent-Type: application/json\n\n" . wp_json_encode(['client_id' => '<internal-App-ID>', 'first_name' => 'New', 'last_name' => 'Patient', 'email' => 'new@example.test', 'password' => '<12–128-character-password>', 'accept_privacy_policy' => true], JSON_PRETTY_PRINT)],
            ['title' => 'Social/OAuth proof', 'text' => 'Social signup uses /auth/challenge with purpose=register, then /auth/register/social with the same app/provider/challenge, signed ID token, names and consent. External signup uses /auth/register/oauth with the internal OAuth App ID and provider token. Require provider and local account:register scope plus verified email claims. Never auto-join existing WordPress accounts by email or let the client choose role/Cliniko ID.'],
            ['title' => 'Receipt lifecycle', 'text' => 'HTTP 202 returns data.registration_token and a generic verification_pending message. Store the 24-hour receipt securely; send it in JSON with the same App ID to /auth/registration/status or /auth/registration/resend. It cannot authorize /me. After ready_to_sign_in, perform normal login. The website verification link is never returned through this API. Unknown fields are rejected.'],
        ];
        if ($key === 'wordpress') return [
            ['title' => 'Login request', 'code' => 'POST ' . $base . '/auth/login' . "\nContent-Type: application/json\n\n" . wp_json_encode(['client_id' => '<approved-public-App-ID>', 'identifier' => 'alex@example.test', 'password' => '<patient-password>'], JSON_PRETTY_PRINT)],
            ['title' => 'Session handling', 'text' => 'Read data.access_token and data.refresh_token from the success envelope. Send the access token as Authorization: Bearer on /me operations. Renew with /auth/refresh and replace both tokens atomically; serialize refreshes. Logout with /auth/logout and the latest refresh token. Never log credentials or put them in URLs/browser localStorage. This is a custom WordPress patient-login flow, not an OAuth password grant.'],
            ['title' => 'Interactive-login compatibility', 'text' => 'wp_authenticate hooks run, but an API call cannot automatically execute interactive MFA/CAPTCHA steps. Known MFA integrations are conservatively blocked. Custom integrations can force blocking with wp_cliniko_api_app_login_requires_browser. Do not return false from this filter just to bypass mandatory authentication. No WordPress authentication cookie is issued.'],
        ];
        if ($key === 'social') return [
            ['title' => 'Challenge and exchange', 'code' => 'POST ' . $base . '/auth/challenge' . "\nContent-Type: application/json\n\n" . wp_json_encode(['client_id' => '<approved-public-App-ID>', 'provider' => 'google'], JSON_PRETTY_PRINT)],
            ['title' => 'Provider SDK', 'text' => 'Use the returned data.nonce in the Google/Apple authorization request. Apple nonce is already SHA-256 transformed: do not hash it again. SDK flows without nonce support are incompatible. Handle provider state, exact redirects and native PKCE where applicable in the provider SDK/flow. Return the provider ID token and challenge_id to /auth/social, with the same client_id and provider. Never send an ID token directly to /me.'],
            ['title' => 'Validation and linking', 'text' => 'The website verifies RS256 signature using fixed provider JWKS URLs, exact issuer, this app’s audience, expiry and single-use nonce. Link canonical issuer + verified subject to the existing patient. No automatic email matching, no account provisioning and no Google/Apple API access scopes are granted by this exchange. Resulting WordPress-issued JWT sessions are revoked locally; external-provider account revocation is not polled after exchange.'],
        ];
        if ($key === 'oauth') return [
            ['title' => 'What you are building', 'text' => 'OAuth lets a patient authorize their application without giving the application their WordPress password. A bearer access token represents that authorization. WordPress acts as the API/resource server and asks the configured identity provider to validate the token. The provider runs the login and token issuance flow.'],
            ['title' => 'What “bearer” means', 'text' => 'Whoever holds the access token can present it until it expires or is rejected. Send it only over HTTPS in the Authorization header, keep it out of URLs and ordinary logs, and use the platform’s secure token storage. An ID token describes the login; it is not the API access token. A refresh token is sent to the provider, never to this API.'],
            ['title' => 'The request journey', 'flow' => ['Patient opens provider login in the system browser', 'Provider returns an authorization code to the app', 'App exchanges the code with its PKCE verifier for an access token', 'App calls this API with Authorization: Bearer', 'WordPress checks the provider response, local client, scopes and patient mapping']],
            ['title' => 'Three identifiers that are easy to confuse', 'table' => ['headings' => ['Identifier', 'Example', 'Where it belongs'], 'rows' => [
                ['Mobile public client ID', 'patient-mobile-app', 'Provider client ID under Applications. It appears as client_id in introspection.'],
                ['Confidential resource-server client ID', 'wordpress-cliniko-resource-server', 'Website connection ID in the guided setup (introspection client ID). Its secret is stored on WordPress only.'],
                ['API audience', 'cliniko-patient-api', 'API name at the sign-in service in the guided setup. It must match the token’s aud claim.'],
            ]]],
            ['title' => 'Before you begin', 'items' => ['An HTTPS WordPress website and an active, verified WordPress patient linked to Cliniko.', 'A provider that supports Authorization Code + PKCE for public native clients and RFC 7662 HTTPS introspection with client-secret Basic authentication.', 'A provider administrator/developer who can supply the issuer, audience, introspection URL, confidential client credentials and staging patient subject.']],
            ['title' => '1. Prepare the provider applications', 'text' => 'At the provider, register a public mobile application, require PKCE, allow its exact redirect URI and approve its requested scopes. Separately create/approve a confidential resource-server client that may call introspection. Obtain its client ID/secret. This plugin does not configure those provider-side applications for you.'],
            ['title' => '2. Confirm the provider response is compatible', 'text' => 'The plugin accepts opaque or JWT access tokens through introspection; it does not decode an unverified JWT to identify a patient. The provider must return all the following fields for a valid token. Some are optional in RFC 7662 but required by this implementation. aud may be a string or an array containing the expected audience.', 'code' => json_encode(['active' => true, 'token_type' => 'Bearer', 'exp' => 1893456000, 'iss' => 'https://identity.example.com/realms/patients', 'aud' => 'cliniko-patient-api', 'sub' => 'provider-user-7', 'client_id' => 'patient-mobile-app', 'scope' => 'patient:read appointments:read'], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES)],
            ['title' => '3. Enter the server-side settings', 'text' => 'In Patient login, enter the exact issuer, audience, introspection URL and confidential introspection client ID/secret. Enable sign-in and save its settings. Separately enable API Access and Patient profile and appointments under Publish API. Keep values aligned with the provider; a trailing slash in iss matters.'],
            ['title' => '4. Register the mobile client locally', 'text' => 'Under Applications, select OAuth mobile/browser application. Enter patient-mobile-app as the Provider client ID, select patient:read and appointments:read, and choose a local approval expiry. The API intersects these local scopes with the provider token’s scopes.'],
            ['title' => '5. Map the staging patient', 'text' => 'Add the exact issuer plus provider subject, such as provider-user-7, and the WordPress patient user ID, such as 7. Obtain the subject from controlled provider tooling, not from an email guess or a public token-decoder website. Confirm the local account is active and already has a verified Cliniko link. Mapping does not create or verify accounts.'],
            ['title' => '6. Test connectivity, then test the real login flow', 'text' => 'Click Check saved connection in the guided setup. It submits a random invalid token and expects active: false. This checks reachability and the confidential credential, not a patient login. A credential/settings fingerprint invalidates old check results after saved changes. Your mobile developer must then perform browser Authorization Code + PKCE and call /me with the resulting staging access token.', 'code' => 'GET ' . $base . '/me' . "\nAuthorization: Bearer <staging-access-token>\nAccept: application/json"],
            ['title' => '7. Handle expiry and revoke access when needed', 'text' => 'The provider owns refresh-token rules. When an access token expires, the app follows the provider’s supported refresh or login flow. The API checks token state on each request. Staff can revoke the local application approval or remove a subject mapping to block the relevant future requests.'],
            ['title' => 'When the test fails', 'table' => ['headings' => ['Error code / symptom', 'What to check'], 'rows' => [
                ['oauth_unconfigured / HTTP 503', 'OAuth enabled flag, saved settings and saved introspection secret.'],
                ['oauth_unavailable / HTTP 503', 'Public HTTPS introspection URL, provider client credentials, reachability and HTTP 200 JSON response. Redirects are not followed.'],
                ['invalid_token / HTTP 401', 'Use an active bearer access token with a future exp; do not send an ID token or refresh token.'],
                ['invalid_token_claims / HTTP 401', 'Exact issuer/audience and required sub, client_id and scope fields.'],
                ['client_denied or insufficient_scope / HTTP 403', 'Registered provider client ID, local approval expiry, and scope on both sides.'],
                ['patient_mapping_required or patient_inactive / HTTP 403', 'Exact issuer + subject mapping, WordPress user ID and active account status.'],
                ['patient_email_verification_required / HTTP 403', 'Complete the existing Cliniko patient email-verification flow first.'],
            ]]],
            ['title' => 'Further reading', 'links' => [['label' => 'Token introspection (RFC 7662)', 'url' => 'https://www.rfc-editor.org/rfc/rfc7662'], ['label' => 'OAuth for native apps (RFC 8252)', 'url' => 'https://www.rfc-editor.org/rfc/rfc8252']]],
        ];
        if ($key === 'server') return [
            ['title' => 'When to use this tutorial', 'text' => 'Use this for a trusted backend service that can store a secret, such as a partner service-list server. A generated server key can read published services, blank forms, clinicians and available times according to its scopes. It cannot create bookings, process payments, read booking progress or access patient-account /me endpoints.'],
            ['title' => '1. Prepare one read-only route', 'text' => 'Enable the API and Booking discovery. Select the Cliniko services you want to expose under Published appointment types, save, and inspect Endpoint documentation for the active /appointment-types route. The picker stores their numeric Cliniko IDs in the exposure allowlist.'],
            ['title' => '2. Register the backend', 'text' => 'Under Applications, select Trusted server integration, give it a recognizable name, choose catalog:read, and set a future expiry. Leave Provider client ID empty. Add availability:read only if the backend needs slots/practitioners.'],
            ['title' => '3. Store the one-time credential', 'text' => 'Copy the generated key when it is shown. Store it in your backend’s secret configuration. The plugin stores a keyed hash and cannot show the original later. Keep it out of browser bundles, mobile apps and source control.'],
            ['title' => '4. Send a scoped request', 'text' => 'Your backend sends the key in the Authorization header. Do not put it in the URL. Use the current base URL shown in this dashboard.', 'code' => 'GET ' . $base . '/appointment-types' . "\nAuthorization: Bearer <server-credential>\nAccept: application/json"],
            ['title' => '5. Maintain the approval', 'text' => 'Use Edit scopes / expiry in the application row to change permissions. Rotate key issues a replacement and immediately invalidates the original; update your backend configuration accordingly. Revoke blocks the next request. Read Audit events to see local client IDs and last-use metadata.'],
            ['title' => 'Expected outcome', 'text' => 'The request returns ok: true with the published appointment types. A valid key without catalog:read returns insufficient_scope; an expired, rotated or revoked key is rejected. Public discovery can also be called anonymously, but supplying an invalid credential never silently downgrades to anonymous access.'],
        ];
        if ($key === 'booking') {
            $example = [];
            foreach (EndpointCatalog::definitions() as $endpoint) if ($endpoint['key'] === 'patient_booking_create') $example = $endpoint['example'];
            return [
                ['title' => 'Create a booking flow just for the app', 'text' => 'Open Booking flows and create an API-only flow: name, identifier, appointment type, questionnaire, scheduling and payment. Save a draft, then open it to review questions and optional answer checks. No shortcode, layout, patient-review screen, redirect or custom code is needed. The app controls its own screens. Existing website-linked publications are labelled Legacy; Make API-only copies only their booking rules to the same API address without changing their web form.'],
                ['title' => 'What a booking attempt does', 'text' => 'An attempt validates the signed-in verified patient’s booking before finalization. It stores the authoritative service, patient context, price and payment reference on the server. It creates draft Cliniko records and returns a secret. It does not reserve the time slot or create a final appointment immediately.'],
                ['title' => '1. Publish the booking resources', 'text' => 'Enable Booking discovery, Authenticated patient booking and Booking payment and progress. Select the approved appointment types and form templates using their checkbox lists; numeric IDs are stored automatically. Enable the Published form templates route group if the client needs to retrieve questions. Complete WordPress, social or external OAuth patient-login setup before testing booking. Patient applications need booking:create for writes and booking:read for status checks; add catalog:read and availability:read when retrieving templates, types and slots. Approve these locally and, for OAuth, at the provider.'],
                ['title' => 'Discover and use the flow contract', 'text' => 'After publishing its resources and enabling the API flow, the signed-in app reads GET /booking-flows to discover available flows, then reads GET /booking-flows/{identifier}. Copy the returned submission.body, fill answers and the requested scheduling fields, then POST to /booking-flows/{identifier}/booking-attempts with the same patient Bearer token. The server supplies service, form, price, gateway and patient identity. Reload on booking_definition_changed. Continue with the payment and finalization steps below. The direct /me/booking-attempts contract remains available separately.'],
                ['title' => '2. Retrieve a valid slot and form structure (direct booking alternative)', 'text' => 'For /me/booking-attempts instead of a named flow, read the published type, its practitioners and availability. Use a returned appointment_start value rather than inventing a date. Retrieve the approved form template and build content.sections in the documented shape. The following request is synthetic; replace IDs, time and answers with staging values.'],
                ['title' => '3. Create the attempt', 'text' => 'POST to /me/booking-attempts with the verified patient access token. Supply only practitioner_id and appointment_start in patient; account identity comes from the server. POST /booking-attempts is not exposed. See Endpoint documentation for the appropriate request schema.', 'code' => 'POST ' . $base . '/me/booking-attempts' . "\nAuthorization: Bearer <patient-access-token>\nContent-Type: application/json\n\n" . json_encode($example, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES)],
                ['title' => '4. Save the returned attempt credentials', 'text' => 'Keep attempt.id and attempt.token in secure client storage and send the token in X-ES-Attempt-Token. Access expires after 24 hours; unfinished drafts are subject to the existing 30-minute cleanup job. Always send the original active verified patient access token as Authorization: Bearer, from the same approved application, alongside the booking secret on payment, finalization and progress requests. Neither credential works alone; guest attempts are rejected.'],
                ['title' => '5. Verify payment before finalizing', 'text' => 'When payment.required is true, use stripe-payment with a Stripe tok_ token, or tyro-payment with a paid transaction that matches this attempt’s server-calculated amount and invoice reference. WordPress checks payment; a client-side success label does not prove payment. If the server marks payment as skipped for a free service, proceed to finalization.'],
                ['title' => '6. Finalize and retry safely', 'text' => 'Send a unique Idempotency-Key and reuse it if this same finalization request needs a retry. An already completed attempt returns its previous result. Poll the status route after a timeout before deciding what happened. A finalization interrupted after it began creating an appointment requires clinic reconciliation.', 'code' => 'POST ' . $base . '/booking-attempts/<attempt-id>/finalize' . "\nAuthorization: Bearer <patient-access-token>\nX-ES-Attempt-Token: <attempt-secret>\nIdempotency-Key: booking-finalize-example-001\n\nGET " . $base . '/booking-attempts/<attempt-id>' . "\nAuthorization: Bearer <patient-access-token>\nX-ES-Attempt-Token: <attempt-secret>"],
                ['title' => 'Expected outcome', 'text' => 'A completed response contains the appointment ID and confirmation data. Booking uses only the signed-in patient’s linked identity, never guest matching or submitted identity fields. Payment/finalization operations are serialized, and managed attempts cannot be processed through the legacy /v2 namespace.'],
            ];
        }
        if ($key === 'browser') return [
            ['title' => 'What CORS controls', 'text' => 'A browser checks whether JavaScript from one origin can read API responses from another. CORS handles that browser boundary. It does not log a patient in or grant API scopes. Native apps usually do not need this setting.'],
            ['title' => '1. Identify the exact frontend origin', 'text' => 'Use scheme + hostname + optional port, for example https://portal.example.com. Do not enter a page path, callback path, wildcard, or the provider issuer unless the frontend is actually hosted there.'],
            ['title' => '2. Save the approved origins', 'text' => 'In Publish API, enter one exact HTTPS origin per line in Allowed browser origins and save. HTTP origins, including localhost with a port, are accepted only when the WordPress environment type is local or development; staging/production reject them even if previously saved. The same-site origin is allowed for requests; only configured cross-origin sites receive the managed CORS allow header.'],
            ['title' => '3. Authenticate the application separately', 'text' => 'A patient browser application still needs an OAuth access token with the approved client ID, scopes and subject mapping. Put Authorization in the request headers. A public discovery request does not require a patient token.', 'code' => "fetch('" . $base . "/me', {\n  headers: {\n    Authorization: 'Bearer <access-token>',\n    Accept: 'application/json'\n  }\n});"],
            ['title' => '4. Inspect the browser network panel', 'text' => 'Confirm the Origin matches the saved value, and that the preflight allows Authorization and the required methods. origin_denied indicates an origin-policy problem. An HTTP 401/403 from the operation indicates a credential, scope or patient-policy problem. Do not solve a token problem by adding a wildcard CORS origin.'],
        ];
        if ($key === 'migration') return [
            ['title' => 'What changes when you rename the slug', 'text' => 'All managed API operation URLs change. Client credentials and OAuth issuer/audience settings are separate and do not change automatically. The old namespace remains a deprecated alias for 30 days.'],
            ['title' => '1. List the current consumers', 'text' => 'Identify website code, mobile releases and partner backends using the current base URL. Pick a unique replacement slug and a migration window that lets those clients update.'],
            ['title' => '2. Confirm and save the new slug', 'text' => 'In Settings, change API base slug, check Confirm changing an active base URL, and save. Verify the new address and the old alias using GET /status. Namespace collisions must be resolved rather than overriding another API.'],
            ['title' => '3. Distribute updated configuration', 'text' => 'Download a fresh OpenAPI contract and update app/backend base URLs. The alias calls the same handlers and emits deprecation/sunset headers; POST clients do not need to follow redirects.'],
            ['title' => '4. Complete the migration before expiry', 'text' => 'Read the alias expiry date in Settings and confirm every supported client has moved. After 30 days the old alias is no longer registered. Keep the public API contract compatible throughout the rename.'],
        ];
        return [
            ['title' => '1. Record the response, without recording secrets', 'text' => 'Note the HTTP status, error.code and meta.request_id (or X-Request-ID). Do not paste access tokens, server keys, introspection secrets or patient answers into ordinary logs/support tickets.'],
            ['title' => '2. Confirm the endpoint is active', 'text' => 'Open Endpoint documentation, find the exact method/path and check the active status. Verify the base URL, master switch, group switches and required published IDs. Disabled or unpublished operations return 404.'],
            ['title' => '3. Match the error to the responsible setting', 'table' => ['headings' => ['Response', 'Next check'], 'rows' => [
                ['401', 'Valid bearer access token or current unexpired server key.'],
                ['403', 'Client approval, required scopes, origin, patient mapping/verification, or attempt secret/owner.'],
                ['409', 'Attempt busy, changed idempotency key, previously used key, or interrupted finalization requiring review.'],
                ['422', 'Validation details or server-side payment rejection. Check the endpoint request schema.'],
                ['429', 'Read/write budgets; respect Retry-After.'],
                ['503', 'API storage initialization, configured OAuth provider or Cliniko availability.'],
            ]]],
            ['title' => '4. Correlate the audit event and retry deliberately', 'text' => 'Use the generated request ID in Audit events to identify the operation, client and status. For a booking timeout, check attempt status before retrying. Use the original Idempotency-Key for finalization and contact the clinic when review_required is reported.'],
        ];
    }

    public static function renderBlocks(array $blocks): void
    {
        foreach ($blocks as $block) {
            if (isset($block['developer'])) {
                echo '<details class="cliniko-api-developer-notes"><summary>' . esc_html($block['title']) . '</summary><div class="cliniko-api-developer-body">';
                self::renderBlocks($block['developer']);
                echo '</div></details>';
                continue;
            }
            echo '<section class="cliniko-api-help-section"><h3>' . esc_html($block['title']) . '</h3>';
            if (isset($block['text'])) echo '<p>' . esc_html($block['text']) . '</p>';
            foreach (['items', 'flow'] as $listKey) {
                if (!isset($block[$listKey])) continue;
                $tag = $listKey === 'flow' ? 'ol' : 'ul';
                echo '<' . $tag . ' class="' . ($listKey === 'flow' ? 'cliniko-api-flow' : 'cliniko-api-help-list') . '">';
                foreach ($block[$listKey] as $item) echo '<li>' . esc_html($item) . '</li>';
                echo '</' . $tag . '>';
            }
            if (isset($block['code'])) echo '<pre><code>' . esc_html($block['code']) . '</code></pre>';
            if (isset($block['table'])) {
                echo '<div class="cliniko-api-table-scroll"><table class="widefat striped"><thead><tr>';
                foreach ($block['table']['headings'] as $heading) echo '<th scope="col">' . esc_html($heading) . '</th>';
                echo '</tr></thead><tbody>';
                foreach ($block['table']['rows'] as $row) {
                    echo '<tr>'; foreach ($row as $cell) echo '<td>' . esc_html($cell) . '</td>'; echo '</tr>';
                }
                echo '</tbody></table></div>';
            }
            if (isset($block['links'])) {
                echo '<ul class="cliniko-api-help-list">';
                foreach ($block['links'] as $link) echo '<li><a href="' . esc_url($link['url']) . '" target="_blank" rel="noopener noreferrer">' . esc_html($link['label']) . '</a></li>';
                echo '</ul>';
            }
            echo '</section>';
        }
    }
}
